test('vatSummary handles mixed VAT rates in single invoice', () => {
  // PRINT-A4 (9% VAT) and DES-HOUR (21% VAT) in one invoice
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 1 }, // 37 base, 3 vat (9%)
      { sku: 'DES-HOUR', qty: 2 }, // 17000 base, 3570 vat (21%)
    ],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const r = vatSummary([issued]);

  assert.equal(r.length, 2);
  // 21% rate first (highest)
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 17000);
  assert.equal(r[0].vat, 3570);
  // 9% rate second
  assert.equal(r[1].rate, 9);
  assert.equal(r[1].base, 37);
  assert.equal(r[1].vat, 3); // 37 * 0.09 = 3.33, rounds to 3
});

test('vatSummary does not mutate input array', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const invoices = [issued];
  const snapshot = JSON.stringify(invoices);

  vatSummary(invoices);

  assert.equal(JSON.stringify(invoices), snapshot);
});

